/* ===== Enquiry forms (admissions, alumni, volunteer, general) =====
   Each form: class="enquiry-form" data-enquiry="<type>" and fields named name/org/email/mobile/pack/message,
   plus the honeypot input name="website". Posts form:'enquiry' to BACKEND_URL; falls back to mailto. */
function submitEnquiry(e) {
  e.preventDefault();
  const f = e.target;
  const type = f.getAttribute('data-enquiry') || 'Enquiry';
  function v(n) { const el = f.elements[n]; return el ? String(el.value || '').trim() : ''; }
  let ok = true, first = null;
  Array.prototype.forEach.call(f.querySelectorAll('[data-req]'), function (el) {
    const kind = el.getAttribute('data-req');
    const val = String(el.value || '').trim();
    let good = val.length >= 2;
    if (kind === 'email') good = EMAIL_RE.test(val);
    else if (kind === 'mobile') good = /^[6-9][0-9]{9}$/.test(normMobile(val));
    else if (kind === 'text') good = val.length >= 5;
    el.classList.toggle('invalid', !good);
    const er = f.querySelector('[data-err-for="' + el.name + '"]');
    if (er) er.classList.toggle('show', !good);
    if (!good && !first) first = el;
    ok = ok && good;
  });
  if (!ok) { if (first) first.focus(); return; }
  const mobile = v('mobile') ? normMobile(v('mobile')) : '';
  const payload = { form: 'enquiry', ref: newRef(), type: type, name: v('name'), org: v('org'), email: v('email'),
    mobile: mobile, pack: v('pack'), message: v('message'), website: v('website') };
  const btn = f.querySelector('button[type=submit]');
  if (btn) btn.disabled = true;
  postToBackend(payload).then(function (res) {
    if (btn) btn.disabled = false;
    if (res) {
      f.reset();
      toast('Thank you. Your message (' + res.ref + ') has reached the Trust. We will reply within 3 working days.',
            'धन्यवाद। आपका संदेश (' + res.ref + ') ट्रस्ट को मिल गया है। हम 3 कार्यदिवस में उत्तर देंगे।');
    } else {
      const subject = '[' + type + '] ' + payload.name + ' — ' + payload.ref;
      const body = 'To: Narain Dass Rastogi Charitable Trust\n\n' +
        'Type: ' + type + '\n' +
        'Name: ' + payload.name + '\n' +
        (payload.org ? 'Organisation / city: ' + payload.org + '\n' : '') +
        (payload.email ? 'Email: ' + payload.email + '\n' : '') +
        (payload.mobile ? 'Mobile: ' + payload.mobile + '\n' : '') +
        (payload.pack ? 'Details: ' + payload.pack + '\n' : '') +
        '\n' + payload.message + '\n\nReference: ' + payload.ref + '\n';
      window.location.href = 'mailto:' + TRUST_EMAIL + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
    }
  });
}

/* ===== Donation options: UPI card, bank details by amount, monthly pledge, company / CSR =====
   Account rule: up to ₹1,00,000 → …5404; above ₹1,00,000 → …5405 (bank transfer only). */
const ACC_SMALL = '2347110110055404', ACC_BIG = '2347110110055405';
const BANK_IFSC = 'UJVN0002347', BANK_ACC_NAME = 'NARAIN DAS RASTOGI CHARITABLE TRUST', BANK_BRANCH = 'Ujjivan Small Finance Bank, Noida Branch';
const GSTIN_RE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/;
const MONTHS_EN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const MONTHS_HI = ['जनवरी','फ़रवरी','मार्च','अप्रैल','मई','जून','जुलाई','अगस्त','सितंबर','अक्टूबर','नवंबर','दिसंबर'];
function LL(en, hi) { return '<span data-lang="en">' + en + '</span><span data-lang="hi">' + hi + '</span>'; }
function isBig(a) { return Number(a) > UPI_MAX; }
function accFor(a) { return isBig(a) ? ACC_BIG : ACC_SMALL; }
function isMobileUa() { return /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || '') || (navigator.maxTouchPoints > 1 && /Macintosh/.test(navigator.userAgent || '')); }
function copyBtn(text) {
  return '<button type="button" class="copy-btn flex-shrink-0 whitespace-nowrap px-2.5 py-1 rounded-full text-[11px] font-semibold border border-ink/15 bg-white hover:bg-sand" data-copy-text="' + esc(text) + '">' + LL('Copy', 'कॉपी करें') + '</button>';
}
/* UPI card: the bank's signed merchant QR, never with an amount added. */
function upiCardHtml(amount) {
  const amt = amount ? inr(amount) : '';
  const pay = isMobileUa()
    ? '<a href="' + esc(UPI_QR_PAYLOAD) + '" class="mt-3 block text-center w-full py-3 rounded-full bg-ink text-white text-sm font-semibold hover:bg-ink/90 transition">' + LL('Pay with UPI app', 'UPI ऐप से भुगतान करें') + '</a>'
    : '';
  const enterAmt = amt
    ? LL('Enter ' + amt + ' yourself in the UPI app.', 'राशि ' + amt + ' UPI ऐप में स्वयं भरें।')
    : LL('Enter the amount yourself in the UPI app.', 'राशि UPI ऐप में स्वयं भरें।');
  return '<div class="text-xs font-bold uppercase tracking-wider text-crimson">' + LL('Pay by UPI', 'UPI से भुगतान') + '</div>' +
    '<img src="' + UPI_QR_IMAGE + '" width="192" height="192" alt="UPI QR code of the Trust\'s Ujjivan merchant account" class="mt-3 mx-auto block w-48 h-48 bg-white rounded-xl border border-ink/10 p-2" />' +
    '<p class="text-xs font-semibold text-ink mt-3 text-center">' + LL('Payee shows as the Trust\'s Ujjivan merchant account', 'प्राप्तकर्ता के रूप में ट्रस्ट का Ujjivan मर्चेंट खाता दिखेगा') + '</p>' +
    '<div class="mt-2 flex flex-wrap items-center justify-center gap-2"><span class="text-[11px] text-slate">UPI ID</span><strong class="font-mono text-ink text-sm break-all">' + esc(UPI_VPA) + '</strong>' + copyBtn(UPI_VPA) + '</div>' +
    pay +
    '<p class="text-[11px] text-slate mt-2 text-center">' + (pay ? '' : LL('Scan with your phone. ', 'फ़ोन से स्कैन करें। ')) + enterAmt + '</p>' +
    '<p class="text-[11px] text-slate mt-1 text-center">' + LL('Works with GPay • PhonePe • Paytm • BHIM and any UPI app', 'GPay • PhonePe • Paytm • BHIM और किसी भी UPI ऐप से') + '</p>';
}
function bankRow(en, hi, value, mono, copy) {
  return '<div class="flex flex-wrap items-center justify-between gap-2 py-1.5 border-b border-ink/5 last:border-0">' +
    '<dt class="text-slate text-xs">' + LL(en, hi) + '</dt>' +
    '<dd class="flex items-center gap-2 min-w-0"><strong class="text-ink ' + (mono ? 'font-mono break-all' : 'break-words') + '">' + esc(value) + '</strong>' + (copy ? copyBtn(value) : '') + '</dd></div>';
}
/* Bank details for an amount (or both accounts with the rule when amount is unknown). */
function bankHtml(amount, title) {
  const known = Number(amount) > 0;
  const big = isBig(amount);
  const head = title || (known && big ? LL('Bank transfer (RTGS / NEFT)', 'बैंक ट्रांसफ़र (RTGS / NEFT)') : LL('Bank transfer (NEFT / RTGS / IMPS)', 'बैंक ट्रांसफ़र (NEFT / RTGS / IMPS)'));
  let accRows;
  if (known) {
    accRows = '<p class="mt-1 text-xs font-semibold text-ink">' + (big
      ? LL('Account 2 • for donations above ₹1,00,000', 'खाता 2 • ₹1,00,000 से अधिक के दान के लिए')
      : LL('Account 1 • for donations up to ₹1,00,000', 'खाता 1 • ₹1,00,000 तक के दान के लिए')) + '</p>' +
      '<dl class="mt-3 text-sm">' + bankRow('Account name', 'खाते का नाम', BANK_ACC_NAME, false, true) +
      bankRow('Account number', 'खाता संख्या', accFor(amount), true, true) +
      bankRow('IFSC', 'IFSC', BANK_IFSC, true, true) +
      bankRow('Bank &amp; branch', 'बैंक व शाखा', BANK_BRANCH, false, false) + '</dl>';
  } else {
    accRows = '<dl class="mt-3 text-sm">' + bankRow('Up to ₹1,00,000', '₹1,00,000 तक', ACC_SMALL, true, true) +
      bankRow('Above ₹1,00,000', '₹1,00,000 से अधिक', ACC_BIG, true, true) +
      bankRow('Account name', 'खाते का नाम', BANK_ACC_NAME, false, false) +
      bankRow('IFSC', 'IFSC', BANK_IFSC, true, true) +
      bankRow('Bank &amp; branch', 'बैंक व शाखा', BANK_BRANCH, false, false) + '</dl>';
  }
  return '<div class="text-xs font-bold uppercase tracking-wider text-crimson">' + head + '</div>' + accRows +
    '<p class="text-[11px] text-slate mt-2">' + LL('Trust PAN: AAATN1994L', 'ट्रस्ट PAN: AAATN1994L') + '</p>';
}
/* UPI (only up to ₹1,00,000) + bank, side by side on wide screens. */
function payDetailsHtml(amount, bankTitle, bankExtra) {
  const upi = UPI_VPA && !isBig(amount);
  return '<div class="grid ' + (upi ? 'md:grid-cols-2 ' : '') + 'gap-4">' +
    (upi ? '<div class="p-5 rounded-2xl bg-ivory border border-ink/10">' + upiCardHtml(amount) + '</div>' : '') +
    '<div class="p-5 rounded-2xl bg-ivory border border-ink/10">' + bankHtml(amount, bankTitle) + (bankExtra || '') +
    (UPI_VPA && isBig(amount) ? '<p class="text-[11px] text-slate mt-2">' + LL('UPI is offered only for amounts up to ₹1,00,000.', 'UPI केवल ₹1,00,000 तक की राशि के लिए है।') + '</p>' : '') +
    '</div></div>';
}
function setErr(el, errId, ok) {
  el.classList.toggle('invalid', !ok);
  const er = document.getElementById(errId);
  if (er) er.classList.toggle('show', !ok);
  return ok;
}
function mailtoHref(subject, body) { return 'mailto:' + TRUST_EMAIL + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body); }

/* ---- Giver (Individual | Company) and frequency (One-time | Monthly) toggles ---- */
let giver = 'individual', freq = 'once';
function syncFlows() {
  const fo = document.getElementById('flowOnce'), fm = document.getElementById('flowMonthly'), fc = document.getElementById('flowCompany');
  if (!fo) return;
  fo.hidden = !(giver === 'individual' && freq === 'once');
  fm.hidden = !(giver === 'individual' && freq === 'monthly');
  fc.hidden = giver !== 'company';
  document.getElementById('freqWrap').hidden = giver === 'company';
  document.querySelectorAll('[data-giver]').forEach(function (b) { b.setAttribute('aria-pressed', b.getAttribute('data-giver') === giver ? 'true' : 'false'); });
  document.querySelectorAll('[data-freq]').forEach(function (b) { b.setAttribute('aria-pressed', b.getAttribute('data-freq') === freq ? 'true' : 'false'); });
}
document.addEventListener('click', function (e) {
  const g = e.target.closest('[data-giver]'), f = e.target.closest('[data-freq]');
  if (g) { giver = g.getAttribute('data-giver'); syncFlows(); }
  if (f) { freq = f.getAttribute('data-freq'); syncFlows(); }
});
function applyDonateHash() {
  if (!document.getElementById('flowOnce')) return;
  const h = location.hash;
  if (h === '#company') { giver = 'company'; syncFlows(); }
  else if (h === '#monthly') { giver = 'individual'; freq = 'monthly'; syncFlows(); }
  else return;
  const tgt = document.getElementById('giveAs');
  if (tgt) setTimeout(function () { tgt.scrollIntoView({ block: 'start' }); }, 50);
}
window.addEventListener('hashchange', applyDonateHash);

/* ---- Monthly pledge (no auto-debit; the donor pays each month by UPI or a bank standing instruction) ---- */
let pledge = null;
(function () {
  const sel = document.getElementById('pStart');
  if (!sel) return;
  const d = new Date();
  for (let i = 0; i < 12; i++) {
    const m = (d.getMonth() + i) % 12, y = d.getFullYear() + Math.floor((d.getMonth() + i) / 12);
    const o = document.createElement('option');
    o.value = y + '-' + String(m + 1).padStart(2, '0');
    o.textContent = MONTHS_EN[m] + ' ' + y;
    o.setAttribute('data-hi', MONTHS_HI[m] + ' ' + y);
    sel.appendChild(o);
  }
  const day = document.getElementById('pDay');
  for (let k = 1; k <= 28; k++) { const o = document.createElement('option'); o.value = String(k); o.textContent = String(k); day.appendChild(o); }
  day.value = '5';
})();
function monthLabel(v, hi) { const p = v.split('-'); return (hi ? MONTHS_HI : MONTHS_EN)[Number(p[1]) - 1] + ' ' + p[0]; }
function submitPledge(e) {
  e.preventDefault();
  const f = document.getElementById('pledgeForm');
  const g = function (id) { return document.getElementById(id); };
  const mobile = normMobile(g('pPhone').value.trim());
  const amtRaw = g('pAmount').value.trim(), amt = Number(amtRaw);
  const pan = g('pPan').value.trim().toUpperCase(); g('pPan').value = pan;
  let ok = true;
  ok = setErr(g('pName'), 'epName', g('pName').value.trim().length >= 3) && ok;
  ok = setErr(g('pEmail'), 'epEmail', EMAIL_RE.test(g('pEmail').value.trim())) && ok;
  ok = setErr(g('pPhone'), 'epPhone', /^[6-9][0-9]{9}$/.test(mobile)) && ok;
  ok = setErr(g('pAmount'), 'epAmount', /^\d+$/.test(amtRaw) && amt >= 1) && ok;
  ok = setErr(g('pPan'), 'epPan', pan === '' || PAN_RE.test(pan)) && ok;
  const day = Number(g('pDay').value);
  ok = setErr(g('pDay'), 'epDay', day >= 1 && day <= 28) && ok;
  ok = setErr(g('pStart'), 'epStart', /^\d{4}-\d{2}$/.test(g('pStart').value)) && ok;
  if (!ok) { const first = f.querySelector('.invalid'); if (first) first.focus(); return; }
  pledge = { ref: newRef(), name: g('pName').value.trim(), email: g('pEmail').value.trim(), mobile: mobile, amount: amt,
    pan: pan, day: day, start: g('pStart').value };
  const payload = { form: 'donation', frequency: 'monthly', ref: pledge.ref, name: pledge.name, email: pledge.email, mobile: pledge.mobile,
    amount: pledge.amount, pan: pledge.pan, dayOfMonth: pledge.day, startMonth: pledge.start, purpose: 'Monthly pledge',
    website: (g('hpPledge') || {}).value || '' };
  const subject = '[Monthly pledge] ' + pledge.name + ' — ' + inr(pledge.amount) + ' a month from ' + monthLabel(pledge.start) + ' — ' + pledge.ref;
  const body = 'To: Narain Dass Rastogi Charitable Trust\n\nI pledge a monthly donation. This is a pledge, not an auto-debit.\n\n' +
    'Name: ' + pledge.name + '\nEmail: ' + pledge.email + '\nMobile: ' + pledge.mobile + '\n' +
    (pledge.pan ? 'PAN: ' + pledge.pan + '\n' : '') +
    'Monthly amount: ' + inr(pledge.amount) + '\nPreferred day of month: ' + pledge.day + '\nStart month: ' + monthLabel(pledge.start) + '\n' +
    'Frequency: monthly\n\nReference: ' + pledge.ref + '\n';
  const btn = f.querySelector('button[type=submit]'); if (btn) btn.disabled = true;
  postToBackend(payload).then(function (res) {
    if (btn) btn.disabled = false;
    showPledgeDone(!!res, mailtoHref(subject, body));
    if (!res) window.location.href = mailtoHref(subject, body);
  });
}
function showPledgeDone(recorded, mailto) {
  const p = pledge, big = isBig(p.amount);
  document.getElementById('pledgeForm').hidden = true;
  const box = document.getElementById('pledgeDone');
  const si = '<p class="text-xs text-ink font-semibold mt-3">' +
    LL('Set up a monthly standing instruction in your bank\'s app: ' + inr(p.amount) + ' on day ' + p.day + ' of each month, starting ' + monthLabel(p.start) + '.',
       'अपने बैंक के ऐप में मासिक स्टैंडिंग इंस्ट्रक्शन सेट करें: हर महीने की ' + p.day + ' तारीख को ' + inr(p.amount) + ', ' + monthLabel(p.start, true) + ' से।') + '</p>';
  document.getElementById('pledgeTitle').innerHTML = LL('Thank you, ' + esc(p.name) + '. Your pledge of ' + inr(p.amount) + ' a month is noted.',
    'धन्यवाद, ' + esc(p.name) + '। ' + inr(p.amount) + ' प्रति माह का आपका संकल्प दर्ज कर लिया गया है।');
  document.getElementById('pledgeRef').innerHTML = LL('Reference', 'संदर्भ') + ': <strong class="font-mono text-ink">' + esc(p.ref) + '</strong>' +
    (recorded ? '' : ' • ' + LL('Your email app opens with these details; please press send. If it did not open, <a class="text-crimson hover:underline" href="' + esc(mailto) + '">open it again</a> or write to ' + TRUST_EMAIL + '.',
      'आपकी ईमेल ऐप इन विवरणों के साथ खुलेगी; कृपया भेज दें। यदि नहीं खुली, तो <a class="text-crimson hover:underline" href="' + esc(mailto) + '">फिर से खोलें</a> या ' + TRUST_EMAIL + ' पर लिखें।'));
  document.getElementById('pledgePay').innerHTML = payDetailsHtml(p.amount, big ? null : LL('Bank standing instruction', 'बैंक स्टैंडिंग इंस्ट्रक्शन'), si);
  const auto = document.getElementById('pledgeAutopay');
  if (RECURRING_GATEWAY_URL) { auto.href = RECURRING_GATEWAY_URL; auto.hidden = false; } else auto.hidden = true;
  box.hidden = false;
  box.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function editPledge() {
  document.getElementById('pledgeDone').hidden = true;
  document.getElementById('pledgeForm').hidden = false;
  document.getElementById('pledgeForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function icsText(s) { return String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n'); }
function icsFold(line) {
  const enc = new TextEncoder(); let out = '', cur = '', n = 0;
  for (const ch of line) {
    const b = enc.encode(ch).length;
    if (n + b > 74) { out += cur + '\r\n '; cur = ''; n = 1; }
    cur += ch; n += b;
  }
  return out + cur;
}
function downloadPledgeIcs() {
  if (!pledge) return;
  const p = pledge, big = isBig(p.amount);
  const ym = p.start.replace('-', ''), dd = String(p.day).padStart(2, '0');
  const now = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  const desc = 'Your monthly pledge to Narain Dass Rastogi Charitable Trust: ' + inr(p.amount) + ' on day ' + p.day + ' of each month.\n\n' +
    (UPI_VPA && !big ? 'UPI ID: ' + UPI_VPA + ' (payee shows as the Trust\'s Ujjivan merchant account). Enter the amount in your UPI app.\n\n' : '') +
    'Bank transfer / standing instruction:\nAccount name: ' + BANK_ACC_NAME + '\nAccount number: ' + accFor(p.amount) + '\nIFSC: ' + BANK_IFSC + '\nBank: ' + BANK_BRANCH + '\n\n' +
    'After paying, email the UTR to ' + TRUST_EMAIL + ' quoting ' + p.ref + ' for your 80G receipt.\n' +
    'This is your own reminder. The Trust does not auto-debit your account.';
  const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Narain Dass Rastogi Charitable Trust//Monthly pledge//EN', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    'BEGIN:VTIMEZONE', 'TZID:Asia/Kolkata', 'BEGIN:STANDARD', 'DTSTART:19700101T000000', 'TZOFFSETFROM:+0530', 'TZOFFSETTO:+0530', 'TZNAME:IST', 'END:STANDARD', 'END:VTIMEZONE',
    'BEGIN:VEVENT', 'UID:' + p.ref + '@narain-dass-rastogi-trust', 'DTSTAMP:' + now,
    'DTSTART;TZID=Asia/Kolkata:' + ym + dd + 'T100000', 'DTEND;TZID=Asia/Kolkata:' + ym + dd + 'T101500',
    'RRULE:FREQ=MONTHLY;BYMONTHDAY=' + p.day,
    'SUMMARY:' + icsText('Monthly donation – Narain Dass Rastogi Charitable Trust'),
    'DESCRIPTION:' + icsText(desc),
    'BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + icsText('Monthly donation – Narain Dass Rastogi Charitable Trust'), 'TRIGGER:PT0M', 'END:VALARM',
    'END:VEVENT', 'END:VCALENDAR'];
  const ics = lines.map(icsFold).join('\r\n') + '\r\n';
  const blob = new Blob([ics], { type: 'text/calendar;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = 'ndr-trust-monthly-donation.ics';
  document.body.appendChild(a); a.click();
  setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

/* ---- Company / CSR contribution ---- */
let company = null;
function companyAmountChanged() {
  const box = document.getElementById('compBank');
  if (!box) return;
  const raw = document.getElementById('cAmount').value.trim();
  const a = /^\d+$/.test(raw) ? Number(raw) : 0;
  box.innerHTML = bankHtml(a > 0 ? a : null) +
    (a > 0 && !isBig(a) && UPI_VPA ? '<p class="text-[11px] text-slate mt-2">' + LL('UPI is also available for this amount: scan the quick-pay QR at the top of this section.', 'इस राशि के लिए UPI भी उपलब्ध है: इस भाग में ऊपर दिया गया क्विक-पे QR स्कैन करें।') + '</p>'
      : a > 0 ? '<p class="text-[11px] text-slate mt-2">' + LL('Please pay by RTGS or NEFT. UPI is offered only up to ₹1,00,000.', 'कृपया RTGS या NEFT से भुगतान करें। UPI केवल ₹1,00,000 तक है।') + '</p>' : '');
}
(function () {
  const amt = document.getElementById('cAmount');
  if (!amt) return;
  amt.addEventListener('input', companyAmountChanged);
  const pur = document.getElementById('cPurpose');
  pur.addEventListener('change', function () { document.getElementById('cProjectWrap').hidden = pur.value !== 'Specific project'; });
  companyAmountChanged();
})();
function submitCompany(e) {
  e.preventDefault();
  const f = document.getElementById('companyForm');
  const g = function (id) { return document.getElementById(id); };
  const up = function (id) { const v = g(id).value.trim().toUpperCase().replace(/\s+/g, ''); g(id).value = v; return v; };
  const pan = up('cPan'), gst = up('cGstin');
  const phone = normMobile(g('cPhone').value.trim());
  const amtRaw = g('cAmount').value.trim(), amt = Number(amtRaw);
  let ok = true;
  ok = setErr(g('cName'), 'ecName', g('cName').value.trim().length >= 3) && ok;
  ok = setErr(g('cPan'), 'ecPan', PAN_RE.test(pan)) && ok;
  ok = setErr(g('cGstin'), 'ecGstin', gst === '' || GSTIN_RE.test(gst)) && ok;
  ok = setErr(g('cContact'), 'ecContact', g('cContact').value.trim().length >= 3) && ok;
  ok = setErr(g('cDesig'), 'ecDesig', g('cDesig').value.trim().length >= 2) && ok;
  ok = setErr(g('cEmail'), 'ecEmail', EMAIL_RE.test(g('cEmail').value.trim())) && ok;
  ok = setErr(g('cPhone'), 'ecPhone', /^[0-9]{10}$/.test(phone)) && ok;
  ok = setErr(g('cAmount'), 'ecAmount', /^\d+$/.test(amtRaw) && amt >= 1) && ok;
  if (!ok) { const first = f.querySelector('.invalid'); if (first) first.focus(); return; }
  const purpose = g('cPurpose').value === 'Specific project' ? 'Specific project: ' + g('cProject').value : g('cPurpose').value;
  company = { ref: newRef(), company: g('cName').value.trim(), pan: pan, gstin: gst, contact: g('cContact').value.trim(),
    designation: g('cDesig').value.trim(), email: g('cEmail').value.trim(), mobile: phone, amount: amt, purpose: purpose,
    need80g: g('c80g').checked, needCsrPack: g('cCsrPack').checked };
  const payload = Object.assign({ form: 'company', website: (g('hpCompany') || {}).value || '' }, company);
  const yn = function (b) { return b ? 'Yes' : 'No'; };
  const subject = '[Company donation] ' + company.company + ' — ' + inr(company.amount) + ' — ' + company.ref;
  const body = 'To: Narain Dass Rastogi Charitable Trust\n\nCompany contribution details\n\n' +
    'Company name: ' + company.company + '\nPAN: ' + company.pan + '\nGSTIN: ' + (company.gstin || '-') + '\n' +
    'Contact person: ' + company.contact + '\nDesignation: ' + company.designation + '\nEmail: ' + company.email + '\nPhone: ' + company.mobile + '\n' +
    'Amount: ' + inr(company.amount) + '\nPurpose: ' + company.purpose + '\n' +
    'Need 80G receipt: ' + yn(company.need80g) + '\nNeed CSR documentation pack: ' + yn(company.needCsrPack) + '\n\nReference: ' + company.ref + '\n';
  const btn = f.querySelector('button[type=submit]'); if (btn) btn.disabled = true;
  postToBackend(payload).then(function (res) {
    if (btn) btn.disabled = false;
    showCompanyDone(!!res, mailtoHref(subject, body));
    if (!res) window.location.href = mailtoHref(subject, body);
  });
}
function showCompanyDone(recorded, mailto) {
  const c = company;
  document.getElementById('companyForm').hidden = true;
  document.getElementById('companyTitle').innerHTML = LL('Thank you. ' + esc(c.company) + '\'s contribution of ' + inr(c.amount) + ' is noted.',
    'धन्यवाद। ' + esc(c.company) + ' के ' + inr(c.amount) + ' के योगदान का विवरण दर्ज कर लिया गया है।');
  document.getElementById('companyRef').innerHTML = LL('Reference', 'संदर्भ') + ': <strong class="font-mono text-ink">' + esc(c.ref) + '</strong>' +
    (recorded ? '' : ' • ' + LL('Your email app opens with these details; please press send. If it did not open, <a class="text-crimson hover:underline" href="' + esc(mailto) + '">open it again</a> or write to ' + TRUST_EMAIL + '.',
      'आपकी ईमेल ऐप इन विवरणों के साथ खुलेगी; कृपया भेज दें। यदि नहीं खुली, तो <a class="text-crimson hover:underline" href="' + esc(mailto) + '">फिर से खोलें</a> या ' + TRUST_EMAIL + ' पर लिखें।'));
  document.getElementById('companyPay').innerHTML = payDetailsHtml(c.amount);
  const utrSubj = 'UTR for ' + c.ref + ' — ' + c.company + ' — ' + inr(c.amount);
  document.getElementById('companyUtr').href = mailtoHref(utrSubj, 'Company: ' + c.company + '\nAmount: ' + inr(c.amount) + '\nReference: ' + c.ref + '\nUTR / transaction reference: \nDate of payment: \n');
  const done = document.getElementById('companyDone');
  done.hidden = false;
  done.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function editCompany() {
  document.getElementById('companyDone').hidden = true;
  document.getElementById('companyForm').hidden = false;
  document.getElementById('companyForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
}
document.querySelectorAll('[data-upi-pay]').forEach(function (a) { if (isMobileUa()) a.hidden = false; });
/* clear a field's error as soon as it is edited */
document.addEventListener('input', function (e) {
  const el = e.target;
  if (!el.classList || !el.classList.contains('invalid') || !el.closest('#pledgeForm, #companyForm')) return;
  el.classList.remove('invalid');
  const er = document.getElementById('e' + el.id); if (er) er.classList.remove('show');
});
